using AudioBufferSourceNode = gea::NativeHandle<AudioBufferSourceNode_tag>;
using AudioContext = gea::NativeHandle<gea_native_protocol_AudioContext_v1>;
struct AudioDestinationNode_tag;
using AudioDestinationNode = gea::NativeHandle<AudioDestinationNode_tag>;
struct AudioParam_tag;
using AudioParam = gea::NativeHandle<AudioParam_tag>;
struct FetchResponse_tag;
using FetchResponse = gea::NativeHandle<FetchResponse_tag>;
struct GeaAudioBlob_tag;
using GeaAudioBlob = gea::NativeHandle<GeaAudioBlob_tag>;
struct GeaEmbeddedImage_tag;
using GeaEmbeddedImage = gea::NativeHandle<GeaEmbeddedImage_tag>;
struct GeolocationCoordinates_tag;
using GeolocationCoordinates = gea::NativeHandle<GeolocationCoordinates_tag>;
struct GeolocationOptions_tag;
using GeolocationOptions = gea::NativeHandle<GeolocationOptions_tag>;
